// ================== استخراج بيانات الرسالة من WhatsApp Cloud API ==================
// هذه العقدة تلتقط نص الرسالة ورقم هاتف الطالب من الحقول العميقة للـ webhook

const body = $input.first().json.body || $input.first().json;

// المسار القياسي في WhatsApp Cloud API
const entry   = body?.entry?.[0];
const change  = entry?.changes?.[0];
const value   = change?.value;
const message = value?.messages?.[0];

// إذا لم يكن هناك رسالة (مثل تحديث حالة delivered/read) نُعلّم العنصر بأنه غير صالح
if (!message) {
  return [{
    json: {
      isValidTextMessage: false,
      reason: 'no_message_object (probably a status update)'
    }
  }];
}

const messageType = message.type;                       // text / image / audio ...
const senderNumber = message.from;                      // رقم هاتف الطالب
const messageBody = message.text?.body || '';           // نص الرسالة
const phoneNumberId = value?.metadata?.phone_number_id; // معرف رقم واتساب الخاص بك

return [{
  json: {
    isValidTextMessage: messageType === 'text' && messageBody.trim().length > 0,
    messageType,
    senderNumber,
    messageBody,
    phoneNumberId
  }
}];

