// ================== تنظيف استجابة Gemini قبل إرسالها لواتساب ==================
// نستخرج النص من الهيكل العميق ونتعامل مع حالات الحظر (safety) أو الاستجابة الفارغة

const response = $input.first().json;

// المسار القياسي لنص الرد في Gemini
let answer = response?.candidates?.[0]?.content?.parts?.[0]?.text;

// حالة رفض/حظر المحتوى أو استجابة فارغة
if (!answer || answer.trim() === '') {
  answer = 'عذراً، لم أتمكن من توليد إجابة لهذا السؤال. الرجاء إعادة صياغته أو توجيهه للأستاذ زكريا مباشرة.';
}

// تنظيف بسيط: إزالة أي مسافات زائدة في البداية/النهاية
answer = answer.trim();

// حد أقصى لطول رسالة واتساب (~4096 حرف)
if (answer.length > 4000) {
  answer = answer.substring(0, 3990) + '...';
}

// نمرر رقم الطالب (نستدعيه من عقدة الاستخراج للحفاظ عليه)
const senderNumber = $('2. Extract Message Data').first().json.senderNumber;
const phoneNumberId = $('2. Extract Message Data').first().json.phoneNumberId;

return [{
  json: {
    answer,
    senderNumber,
    phoneNumberId
  }
}];

